// Parse criteria and prepare for scraping
const criteriaData = $input.first().json;
const email = criteriaData.email;
const criteria = typeof criteriaData.criteria === 'string' ? JSON.parse(criteriaData.criteria) : criteriaData.criteria;

// Extract form field values
const priceMin = criteria['Price Range Min ($)'] || 0;
const priceMax = criteria['Price Range Max ($)'] || 999999999;
const ebitdaMin = criteria['EBITDA Min ($)'] || 0;
const ebitdaMax = criteria['EBITDA Max ($)'] || 999999999;
const revenueMin = criteria['Revenue Min ($)'] || 0;
const revenueMax = criteria['Revenue Max ($)'] || 999999999;
const location = criteria['Location (city, state, or keywords)'] || '';
const industries = criteria['Industry Keywords (comma-separated)'] || '';
const selectedSites = criteria['Websites to Scrape'] || [];

// Create search URLs for each selected site
const siteUrls = [];

if (selectedSites.includes('BizBuySell')) {
  let url = `https://www.bizbuysell.com/businesses-for-sale/?q=`;
  if (location) url += `location:${encodeURIComponent(location)},`;
  if (priceMin > 0) url += `price_min:${priceMin},`;
  if (priceMax < 999999999) url += `price_max:${priceMax},`;
  siteUrls.push({ site: 'BizBuySell', url, page: 1 });
  siteUrls.push({ site: 'BizBuySell', url, page: 2 });
}

if (selectedSites.includes('BizQuest')) {
  let url = `https://www.bizquest.com/businesses-for-sale/?`;
  if (location) url += `location=${encodeURIComponent(location)}&`;
  if (priceMin > 0) url += `asking_price_from=${priceMin}&`;
  if (priceMax < 999999999) url += `asking_price_to=${priceMax}&`;
  siteUrls.push({ site: 'BizQuest', url, page: 1 });
}

if (selectedSites.includes('Flippa')) {
  let url = `https://flippa.com/search?filter%5Bproperty_type%5D=website&`;
  if (priceMin > 0) url += `filter%5Bprice_min%5D=${priceMin}&`;
  if (priceMax < 999999999) url += `filter%5Bprice_max%5D=${priceMax}&`;
  siteUrls.push({ site: 'Flippa', url, page: 1 });
}

if (selectedSites.includes('Empire Flippers')) {
  let url = `https://empireflippers.com/marketplace/?`;
  if (priceMin > 0) url += `min_price=${priceMin}&`;
  if (priceMax < 999999999) url += `max_price=${priceMax}&`;
  siteUrls.push({ site: 'Empire Flippers', url, page: 1 });
}

if (selectedSites.includes('BusinessBroker.net')) {
  siteUrls.push({ site: 'BusinessBroker.net', url: 'https://www.businessbroker.net/businesses-for-sale/', page: 1 });
}

if (selectedSites.includes('Sunbelt Business Brokers')) {
  siteUrls.push({ site: 'Sunbelt Business Brokers', url: 'https://sunbeltnetwork.com/businesses-for-sale/', page: 1 });
}

if (selectedSites.includes('Transworld Business Advisors')) {
  siteUrls.push({ site: 'Transworld Business Advisors', url: 'https://www.tworld.com/businesses-for-sale/', page: 1 });
}

if (selectedSites.includes('BizBen')) {
  siteUrls.push({ site: 'BizBen', url: 'https://www.bizben.com/businesses-for-sale', page: 1 });
}

if (selectedSites.includes('DealStream')) {
  siteUrls.push({ site: 'DealStream', url: 'https://www.dealstream.com/deals/', page: 1 });
}

if (selectedSites.includes('Axial')) {
  siteUrls.push({ site: 'Axial', url: 'https://www.axial.net/businesses-for-sale/', page: 1 });
}

return siteUrls.map(item => ({
  json: {
    ...item,
    email,
    priceMin,
    priceMax,
    ebitdaMin,
    ebitdaMax,
    revenueMin,
    revenueMax,
    location,
    industries
  }
}));

// Extract listings from HTML
const html = $input.first().json.body || '';
const site = $input.first().json.site;
const criteria = $input.first().json;

const listings = [];

try {
  // Generic extraction pattern (simplified - real scraping needs site-specific selectors)
  // This is a placeholder - in production, use proper HTML parsing per site

  if (site === 'BizBuySell') {
    // Simplified extraction - real implementation needs cheerio or similar
    const titleRegex = /<a[^>]*class="[^"]*listing-title[^"]*"[^>]*>([^<]+)<\/a>/gi;
    const priceRegex = /\$([\d,]+)/g;
    const urlRegex = /href="([^"]*\/business-[^"]+)"/gi;

    let match;
    let index = 0;
    while ((match = titleRegex.exec(html)) !== null && index < 20) {
      const title = match[1].trim();
      const priceMatch = priceRegex.exec(html.substring(match.index, match.index + 500));
      const price = priceMatch ? parseInt(priceMatch[1].replace(/,/g, '')) : 0;
      const urlMatch = urlRegex.exec(html.substring(match.index - 200, match.index + 200));
      const url = urlMatch ? `https://www.bizbuysell.com${urlMatch[1]}` : '';

      if (title && url) {
        listings.push({
          title,
          price,
          ebitda: null,
          revenue: null,
          location: criteria.location || 'N/A',
          description: title,
          url,
          source: site
        });
      }
      index++;
    }
  } else {
    // For other sites, return placeholder data for now
    // Real implementation would have site-specific parsers
    listings.push({
      title: `Sample listing from ${site}`,
      price: 100000,
      ebitda: null,
      revenue: null,
      location: criteria.location || 'N/A',
      description: `Sample business listing from ${site}`,
      url: criteria.url,
      source: site
    });
  }
} catch (error) {
  console.error(`Error parsing ${site}:`, error);
}

// Filter by criteria
const filtered = listings.filter(listing => {
  if (listing.price < criteria.priceMin || listing.price > criteria.priceMax) return false;
  if (listing.ebitda && (listing.ebitda < criteria.ebitdaMin || listing.ebitda > criteria.ebitdaMax)) return false;
  if (listing.revenue && (listing.revenue < criteria.revenueMin || listing.revenue > criteria.revenueMax)) return false;
  return true;
});

return filtered.map(listing => ({ json: { ...listing, email: criteria.email } }));

// Compute MD5 hash for deduplication
const crypto = require('crypto');

const items = $input.all();
return items.map(item => {
  const listing = item.json;
  const hashInput = `${listing.title}||${listing.url}`;
  const hash = crypto.createHash('md5').update(hashInput).digest('hex');

  return {
    json: {
      ...listing,
      hash
    }
  };
});
